import{_ as s,l as r,o as e,c as l,v as o,p as i,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"闭包转换与 lambda 提升","description":"","frontmatter":{"title":"闭包转换与 lambda 提升","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/closure-conversion.md","filePath":"cs/closure-conversion.md","lastUpdated":1789023840000}'),h={name:"cs/closure-conversion.md"};function m(u,a,_,f,E,b){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="闭包转换与-lambda-提升" tabindex="-1">闭包转换与 lambda 提升 <a class="header-anchor" href="#闭包转换与-lambda-提升" aria-label="Permalink to &quot;闭包转换与 lambda 提升&quot;">​</a></h1><div class="epigraph"><p>嵌套函数要变成顶层函数加环境参数。闭包转换把自由变量打成记录；lambda lifting 把自由变量变成额外形参。</p><footer>—— 据 Johnsson, Lambda Lifting；Appel, Compiling with Continuations；Peyton Jones 整理</footer></div><p>上一课<a href="/cs/weak-refs-finalizers">弱引用</a> 收束堆。语言特性落地：表面有嵌套 λ。<a href="/cs/lambda-calculus">λ 演算</a> 的自由变量在实现里要有家。缺口是 <strong>closure conversion / lifting</strong>。CPS 下一课。不重写 β。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>λx. ... y ...</code> 的 \\(y\\) 来自外层。机器没有嵌套作用域。转换：<code>λ(env,x). ... env.y</code>，调用处传闭包指针。缺口是<strong>环境表示</strong>（扁平记录、链），不是 GC 弱。</p><p>提升：把 \\(y\\) 变成参数，调用处传递，适合已知调用点；做成闭包值则必须堆记录。</p><h3 id="闭包不是-c-函数指针" tabindex="-1">闭包不是 C 函数指针 <a class="header-anchor" href="#闭包不是-c-函数指针" aria-label="Permalink to &quot;闭包不是 C 函数指针&quot;">​</a></h3><p>函数指针无环境。带环境的是胖指针 <code>{code, env}</code>。C++ <code>std::function</code>、Rust 闭包各有表示。</p><p><span class="marginnote">Johnsson 1985。Appel CWC。Peyton Jones 实现书。与<a href="/cs/escape-analysis">逃逸</a>：环境未逃逸可栈上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算自由变量。选表示：逃逸则堆闭包。生成顶层函数。调用：间接 <code>code(env, args)</code>。已知闭包+内联则可消间接。</p>',11)),(e(),i(p,null,{default:t(()=>[c(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEST%5B%22%E5%B5%8C%E5%A5%97%20%CE%BB%22%5D%20--%3E%20FV%5B%22%E8%87%AA%E7%94%B1%E5%8F%98%E9%87%8F%22%5D%0A%20%20FV%20--%3E%20ENV%5B%22%E7%8E%AF%E5%A2%83%E8%AE%B0%E5%BD%95%22%5D%0A%20%20ENV%20--%3E%20TOP%5B%22%E9%A1%B6%E5%B1%82%E5%87%BD%E6%95%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与所有权：环境捕获是移动还是借用，接 Rust 课。与 RC：环境字段要计数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>链式环境：共享外层，可变捕获麻烦。扁平：复制，可变要盒。不要捕获后还以为外层栈槽活着——悬空，生命周期课已禁。</p><p>优化：已知函数、无自由变量则退化成函数指针。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CPS。后课默认：嵌套函数降为闭包或提升参数。下一课 CPS 与延续。</p><p>也不把闭包当数学闭包算子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>闭包转换：代码+环境；lifting：自由变量变参数。</li><li>表示受逃逸与可变捕获约束。</li><li>无自由变量则退化为函数指针。</li><li>出处：Johnsson；Appel CWC；Peyton Jones。</li></ul>',9))])}const P=s(h,[["render",m]]);export{A as __pageData,P as default};
